import '../models/models.dart';

class AnnualSecondarySvtUnit {
  final SchoolLevel level;
  final String code, title, lessonId, lessonTitle, summary, content;
  final int unitOrder;
  final List<String> keyPoints;
  final List<Exercise> exercises;
  const AnnualSecondarySvtUnit({
    required this.level, required this.code, required this.unitOrder,
    required this.title, required this.lessonId, required this.lessonTitle,
    required this.summary, required this.content, required this.keyPoints,
    required this.exercises,
  });
  String get subjectId => switch (code) {
    '5e' => 'cinq_svt',
    '4e' => 'quatre_svt',
    '3e' => 'trois_svt',
    _ => 'core_svt_$code',
  };
  String get chapterId => 'core_secondary_svt_${code}_unit_${unitOrder}';
}

const annualSecondarySvtUnits = <AnnualSecondarySvtUnit>[
  AnnualSecondarySvtUnit(level:SchoolLevel.cinquieme,code:'5e',unitOrder:1,title:'Pollution par les déchets solides',lessonId:'core_svt_5e_solid_pollution',lessonTitle:'Identifier les polluants solides et agir',summary:'Reconnaître les déchets solides, leurs effets et les moyens de réduire la pollution.',content:'Les sachets, bouteilles plastiques, piles usagées et autres déchets peuvent polluer le milieu. Les déchets accumulés bouchent les caniveaux, favorisent les inondations et peuvent créer des lieux de reproduction pour certains moustiques. Les piles peuvent libérer des substances nocives. Pour réduire la pollution, il faut limiter les déchets, réutiliser et recycler lorsque c’est possible, collecter les déchets et ne pas brûler les plastiques. Les piles doivent être déposées dans une filière de collecte adaptée.',keyPoints:['Les déchets solides peuvent polluer le sol et l’eau','Les déchets dans les caniveaux aggravent les inondations','Réduire, réutiliser, trier et collecter','Ne pas brûler les plastiques'],exercises:[
    Exercise(id:'core_svt_5e_sp1',lessonId:'core_svt_5e_solid_pollution',question:'Quel déchet peut libérer des substances nocives ?',options:['Une pile usagée','Une feuille propre','Une pierre naturelle'],correctIndex:0,explanation:'Les piles usagées peuvent contenir des substances dangereuses et doivent être collectées.'),
    Exercise(id:'core_svt_5e_sp2',lessonId:'core_svt_5e_solid_pollution',question:'Pourquoi faut-il éviter les déchets dans les caniveaux ?',options:['Ils peuvent bloquer l’écoulement de l’eau','Ils rendent l’eau potable','Ils augmentent la capacité du caniveau'],correctIndex:0,explanation:'Les déchets peuvent obstruer les caniveaux et favoriser les inondations.'),
    Exercise(id:'core_svt_5e_sp3',lessonId:'core_svt_5e_solid_pollution',question:'Quel geste réduit la pollution par les plastiques ?',options:['Réduire et collecter les plastiques','Les brûler à l’air libre','Les jeter dans un cours d’eau'],correctIndex:0,explanation:'La réduction et la collecte évitent leur dispersion dans l’environnement.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.cinquieme,code:'5e',unitOrder:2,title:'Chaînes alimentaires et équilibre',lessonId:'core_svt_5e_food_chain',lessonTitle:'Comprendre une chaîne alimentaire',summary:'Identifier producteurs, consommateurs et décomposeurs.',content:'Une chaîne alimentaire montre les relations alimentaires entre les êtres vivants. Les plantes vertes sont des producteurs : elles fabriquent leur matière organique grâce à la photosynthèse. Les animaux sont des consommateurs. Les décomposeurs, comme certains champignons et micro-organismes, transforment les restes organiques et participent au recyclage de la matière. Plusieurs chaînes reliées forment un réseau alimentaire. La disparition d’un maillon peut perturber l’équilibre du milieu.',keyPoints:['Producteurs : plantes vertes','Consommateurs : animaux','Décomposeurs : recyclage de la matière','Les êtres vivants sont interdépendants'],exercises:[
    Exercise(id:'core_svt_5e_fc1',lessonId:'core_svt_5e_food_chain',question:'Quel organisme est un producteur ?',options:['Une plante verte','Un lion','Un champignon décomposeur'],correctIndex:0,explanation:'Les plantes vertes produisent leur matière organique.'),
    Exercise(id:'core_svt_5e_fc2',lessonId:'core_svt_5e_food_chain',question:'Quel est le rôle des décomposeurs ?',options:['Recycler la matière organique','Produire la lumière du Soleil','Empêcher toute croissance'],correctIndex:0,explanation:'Les décomposeurs transforment les restes organiques et recyclent la matière.'),
    Exercise(id:'core_svt_5e_fc3',lessonId:'core_svt_5e_food_chain',question:'La disparition d’un maillon peut…',options:['Perturber le réseau alimentaire','Ne jamais avoir d’effet','Créer automatiquement de nouvelles espèces'],correctIndex:0,explanation:'Les organismes dépendent les uns des autres dans un réseau alimentaire.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.quatrieme,code:'4e',unitOrder:1,title:'Pollution chimique et ressources naturelles',lessonId:'core_svt_4e_chemical_pollution',lessonTitle:'Prévenir la pollution chimique',summary:'Identifier des polluants chimiques et proposer des mesures de prévention.',content:'Les polluants chimiques peuvent provenir de pesticides, détergents, huiles, rejets industriels ou d’une mauvaise gestion des déchets. Ils peuvent contaminer l’eau et le sol, nuire aux organismes et entrer dans les chaînes alimentaires. La prévention repose sur l’usage raisonné des produits, le respect des consignes, la collecte des huiles et produits dangereux, le traitement des eaux usées et la protection des zones naturelles. Ne manipule jamais un produit chimique inconnu.',keyPoints:['Polluants : pesticides, huiles, certains rejets','Contamination de l’eau et du sol','Prévention : usage raisonné, collecte et traitement','Ne jamais manipuler un produit inconnu'],exercises:[
    Exercise(id:'core_svt_4e_cp1',lessonId:'core_svt_4e_chemical_pollution',question:'Quel exemple peut être un polluant chimique ?',options:['Un pesticide mal utilisé','Une feuille tombée','Une pierre propre'],correctIndex:0,explanation:'Un pesticide mal utilisé peut contaminer le sol et l’eau.'),
    Exercise(id:'core_svt_4e_cp2',lessonId:'core_svt_4e_chemical_pollution',question:'Comment réduire les risques de pollution ?',options:['Respecter les doses et collecter les produits dangereux','Verser l’huile dans la rivière','Mélanger des produits inconnus'],correctIndex:0,explanation:'L’utilisation raisonnée et la collecte limitent la contamination.'),
    Exercise(id:'core_svt_4e_cp3',lessonId:'core_svt_4e_chemical_pollution',question:'Que faire devant un produit chimique inconnu ?',options:['Ne pas le manipuler et prévenir un adulte responsable','Le goûter','Le verser dans le sol'],correctIndex:0,explanation:'Un produit inconnu peut être dangereux ; il faut demander un encadrement.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.quatrieme,code:'4e',unitOrder:2,title:'Roches et phénomènes géodynamiques externes',lessonId:'core_svt_4e_rocks',lessonTitle:'Comprendre l’altération et la formation des roches sédimentaires',summary:'Distinguer quelques types de roches et expliquer l’érosion et la sédimentation.',content:'Les roches peuvent être magmatiques, sédimentaires ou métamorphiques. À la surface, l’eau, le vent, les variations de température et les êtres vivants contribuent à l’altération et à l’érosion. Les fragments transportés se déposent : c’est la sédimentation. Avec le temps, les sédiments peuvent se compacter et se cimenter pour former une roche sédimentaire. Ces phénomènes façonnent les paysages du Togo et d’autres régions.',keyPoints:['Roches : magmatiques, sédimentaires, métamorphiques','Altération et érosion dégradent les roches','Transport puis dépôt : sédimentation','Compaction et cimentation peuvent former une roche sédimentaire'],exercises:[
    Exercise(id:'core_svt_4e_ro1',lessonId:'core_svt_4e_rocks',question:'Quel phénomène transporte des particules de roche ?',options:['L’érosion par l’eau ou le vent','La photosynthèse','La digestion'],correctIndex:0,explanation:'L’eau et le vent peuvent éroder et transporter des particules.'),
    Exercise(id:'core_svt_4e_ro2',lessonId:'core_svt_4e_rocks',question:'La sédimentation correspond…',options:['Au dépôt de particules transportées','À la fusion du noyau terrestre','À la production de lumière'],correctIndex:0,explanation:'La sédimentation est le dépôt de matériaux transportés.'),
    Exercise(id:'core_svt_4e_ro3',lessonId:'core_svt_4e_rocks',question:'Une roche sédimentaire peut se former par…',options:['Compaction et cimentation de sédiments','Refroidissement d’une étoile','Évaporation de tous les minéraux'],correctIndex:0,explanation:'Les sédiments peuvent se compacter et se cimenter.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.troisieme,code:'3e',unitOrder:1,title:'Formations géologiques du Togo',lessonId:'core_svt_3e_togo_geology',lessonTitle:'Étudier les formations géologiques du Togo',summary:'Relier les formations géologiques aux paysages et aux ressources du pays.',content:'Le territoire togolais présente plusieurs ensembles géologiques, dont des formations sédimentaires dans le sud et des formations anciennes dans les régions centrales et septentrionales. Les roches et les sols influencent les reliefs, l’eau souterraine et certaines activités économiques. Pour étudier une formation géologique, on observe sa localisation, sa composition, son âge relatif et ses intérêts ou contraintes. L’exploitation des ressources doit tenir compte de la sécurité et de la protection de l’environnement.',keyPoints:['Le Togo possède plusieurs ensembles géologiques','Roches et sols influencent reliefs et ressources','Étudier localisation, composition et intérêts','L’exploitation doit protéger l’environnement'],exercises:[
    Exercise(id:'core_svt_3e_tg1',lessonId:'core_svt_3e_togo_geology',question:'Les formations géologiques influencent notamment…',options:['Les reliefs et certaines ressources','Uniquement la couleur du ciel','La durée d’une journée'],correctIndex:0,explanation:'Les roches et structures géologiques participent aux reliefs et aux ressources.'),
    Exercise(id:'core_svt_3e_tg2',lessonId:'core_svt_3e_togo_geology',question:'Pour étudier une formation géologique, on observe…',options:['Sa localisation et sa composition','Seulement le nom d’une ville','Uniquement la météo'],correctIndex:0,explanation:'La localisation et la composition sont des repères d’étude géologique.'),
    Exercise(id:'core_svt_3e_tg3',lessonId:'core_svt_3e_togo_geology',question:'L’exploitation d’une ressource doit…',options:['Respecter la sécurité et l’environnement','Ignorer les risques','Polluer volontairement les eaux'],correctIndex:0,explanation:'Une exploitation responsable doit limiter les risques et les impacts.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.troisieme,code:'3e',unitOrder:2,title:'Pollution de l’eau et santé des milieux',lessonId:'core_svt_3e_water_pollution',lessonTitle:'Prévenir la pollution des eaux',summary:'Identifier les sources de pollution de l’eau et leurs effets sur les écosystèmes.',content:'L’eau peut être polluée par les déchets, les eaux usées, certains produits agricoles et les rejets industriels. La pollution peut réduire la qualité de l’eau, perturber les organismes aquatiques et favoriser des risques sanitaires. La prévention comprend l’assainissement, le traitement des eaux usées, la protection des sources et cours d’eau, la réduction des déchets et l’éducation environnementale. Une eau claire n’est pas nécessairement potable : il faut une source sûre et un traitement adapté.',keyPoints:['Sources : déchets, eaux usées, produits chimiques','Effets sur les organismes et la santé','Assainissement et traitement des eaux','L’eau claire n’est pas toujours potable'],exercises:[
    Exercise(id:'core_svt_3e_wp1',lessonId:'core_svt_3e_water_pollution',question:'Quelle source peut polluer un cours d’eau ?',options:['Des eaux usées non traitées','Une source protégée','Un récipient propre fermé'],correctIndex:0,explanation:'Les eaux usées non traitées peuvent contaminer les cours d’eau.'),
    Exercise(id:'core_svt_3e_wp2',lessonId:'core_svt_3e_water_pollution',question:'Une eau claire est-elle toujours potable ?',options:['Non, elle peut contenir des microbes ou substances invisibles','Oui, toujours','Seulement si elle est froide'],correctIndex:0,explanation:'La transparence ne garantit pas la qualité microbiologique ou chimique.'),
    Exercise(id:'core_svt_3e_wp3',lessonId:'core_svt_3e_water_pollution',question:'Quel moyen réduit la pollution de l’eau ?',options:['Traiter les eaux usées','Jeter les déchets dans le fleuve','Laver les pesticides dans un puits'],correctIndex:0,explanation:'Le traitement des eaux usées réduit les polluants rejetés.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.troisieme,code:'3e',unitOrder:3,title:'Commande nerveuse du mouvement',lessonId:'core_svt_3e_nervous_control',lessonTitle:'Comprendre le rôle du système nerveux',summary:'Relier stimulus, organes sensoriels, centres nerveux et muscles.',content:'Le système nerveux permet de recevoir des informations et de coordonner des réponses. Les organes sensoriels détectent un stimulus et transmettent un message nerveux par les nerfs vers les centres nerveux, notamment le cerveau et la moelle épinière. Une réponse motrice est ensuite transmise aux muscles. Certains réflexes sont rapides et involontaires. Protéger le système nerveux implique notamment de prévenir les traumatismes et d’éviter les substances qui altèrent son fonctionnement.',keyPoints:['Stimulus détecté par un organe sensoriel','Message transmis par les nerfs','Cerveau et moelle épinière coordonnent les réponses','Les réflexes sont rapides et involontaires'],exercises:[
    Exercise(id:'core_svt_3e_nc1',lessonId:'core_svt_3e_nervous_control',question:'Quel organe appartient au système nerveux central ?',options:['Le cerveau','Le biceps','La peau uniquement'],correctIndex:0,explanation:'Le cerveau et la moelle épinière constituent le système nerveux central.'),
    Exercise(id:'core_svt_3e_nc2',lessonId:'core_svt_3e_nervous_control',question:'Un réflexe est généralement…',options:['Rapide et involontaire','Toujours lent et volontaire','Sans message nerveux'],correctIndex:0,explanation:'Un réflexe est une réponse rapide et involontaire.'),
    Exercise(id:'core_svt_3e_nc3',lessonId:'core_svt_3e_nervous_control',question:'Les muscles reçoivent une commande motrice grâce…',options:['Aux messages nerveux','Aux roches','À la lumière seule'],correctIndex:0,explanation:'Les messages nerveux transmettent la commande aux muscles.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.cinquieme,code:'5e',unitOrder:3,title:'La cellule, unité du vivant',lessonId:'core_svt_5e_cell',lessonTitle:'Découvrir l’organisation cellulaire',summary:'Comprendre que les êtres vivants sont constitués de cellules.',content:'La cellule est une unité fondamentale du vivant. Certains êtres vivants sont constitués d’une seule cellule, d’autres de nombreuses cellules. Une cellule animale ou végétale possède une membrane et du cytoplasme ; beaucoup possèdent aussi un noyau. Les cellules spécialisées peuvent former des tissus, des organes et des appareils. Les observations au microscope doivent être réalisées avec du matériel adapté.',keyPoints:['La cellule est une unité du vivant','Organisme unicellulaire ou pluricellulaire','Cellules spécialisées → tissus → organes'],exercises:[
    Exercise(id:'core_svt_5e_cell1',lessonId:'core_svt_5e_cell',question:'La cellule est…',options:['Une unité fondamentale du vivant','Un organe uniquement','Un minéral'],correctIndex:0,explanation:'Les êtres vivants sont constitués d’une ou de plusieurs cellules.'),
    Exercise(id:'core_svt_5e_cell2',lessonId:'core_svt_5e_cell',question:'Un être vivant constitué d’une seule cellule est…',options:['Unicellulaire','Pluricellulaire','Inerte'],correctIndex:0,explanation:'Le préfixe uni- signifie un seul.'),
    Exercise(id:'core_svt_5e_cell3',lessonId:'core_svt_5e_cell',question:'Un ensemble de cellules spécialisées forme généralement…',options:['Un tissu','Une planète','Une roche'],correctIndex:0,explanation:'Des cellules semblables et spécialisées peuvent former un tissu.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.cinquieme,code:'5e',unitOrder:4,title:'L’eau dans la nature et dans la vie',lessonId:'core_svt_5e_water_cycle',lessonTitle:'Comprendre le cycle de l’eau',summary:'Décrire évaporation, condensation, précipitation et ruissellement.',content:'Sous l’effet de la chaleur, l’eau des mers, lacs et sols s’évapore. La vapeur se refroidit et se condense en gouttelettes dans les nuages. L’eau retombe sous forme de précipitations. Une partie ruisselle vers les cours d’eau, une autre s’infiltre et alimente les nappes. L’eau est indispensable aux êtres vivants et doit être économisée et protégée contre la pollution.',keyPoints:['Évaporation → condensation → précipitations','Ruissellement et infiltration','Protéger les ressources en eau'],exercises:[
    Exercise(id:'core_svt_5e_wc1',lessonId:'core_svt_5e_water_cycle',question:'La transformation de l’eau liquide en vapeur s’appelle…',options:['Évaporation','Condensation','Solidification'],correctIndex:0,explanation:'L’évaporation transforme l’eau liquide en vapeur.'),
    Exercise(id:'core_svt_5e_wc2',lessonId:'core_svt_5e_water_cycle',question:'La condensation contribue à former…',options:['Les nuages','Les roches magmatiques','Le sable uniquement'],correctIndex:0,explanation:'La vapeur refroidie forme des gouttelettes qui composent les nuages.'),
    Exercise(id:'core_svt_5e_wc3',lessonId:'core_svt_5e_water_cycle',question:'Quelle action protège l’eau ?',options:['Éviter de jeter des déchets dans les cours d’eau','Verser des huiles dans les caniveaux','Laisser couler inutilement les robinets'],correctIndex:0,explanation:'La prévention des déchets et des rejets protège les ressources en eau.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.cinquieme,code:'5e',unitOrder:5,title:'Hygiène et prévention des maladies',lessonId:'core_svt_5e_disease_prevention',lessonTitle:'Prévenir la transmission des maladies',summary:'Identifier des voies de transmission et adopter des gestes de prévention.',content:'Certaines maladies infectieuses sont causées par des micro-organismes et peuvent se transmettre par l’air, l’eau ou les aliments contaminés, le sang ou des vecteurs. La prévention comprend le lavage des mains, l’eau potable, l’assainissement, la vaccination selon les recommandations sanitaires et la protection contre les moustiques. En cas de symptômes persistants, il faut demander conseil à un professionnel de santé.',keyPoints:['Les modes de transmission varient selon la maladie','Hygiène des mains et eau potable','Vaccination et conseils sanitaires adaptés'],exercises:[
    Exercise(id:'core_svt_5e_dp1',lessonId:'core_svt_5e_disease_prevention',question:'Quel geste aide à prévenir certaines infections ?',options:['Se laver les mains au savon','Partager une eau contaminée','Laisser les aliments exposés'],correctIndex:0,explanation:'Le lavage des mains réduit la transmission de nombreux agents infectieux.'),
    Exercise(id:'core_svt_5e_dp2',lessonId:'core_svt_5e_disease_prevention',question:'Pour prévenir certaines maladies transmises par les moustiques, on peut…',options:['Éliminer les eaux stagnantes','Conserver des récipients ouverts pleins d’eau','Dormir près des déchets'],correctIndex:0,explanation:'Réduire les eaux stagnantes limite les lieux de reproduction des moustiques.'),
    Exercise(id:'core_svt_5e_dp3',lessonId:'core_svt_5e_disease_prevention',question:'Une vaccination doit suivre…',options:['Les recommandations sanitaires','Un dosage choisi au hasard','Une recette familiale'],correctIndex:0,explanation:'Les vaccinations se font selon les recommandations sanitaires adaptées.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.cinquieme,code:'5e',unitOrder:6,title:'Le sol : formation et protection',lessonId:'core_svt_5e_soil',lessonTitle:'Comprendre la formation et le rôle du sol',summary:'Reconnaître les composants du sol et les actions qui le protègent.',content:'Le sol se forme lentement par l’altération des roches et l’accumulation de matière organique. Il contient des particules minérales, de l’humus, de l’eau, de l’air et des êtres vivants. Le sol permet l’enracinement des plantes, stocke une partie de l’eau et abrite de nombreux organismes. Le déboisement, l’érosion et la pollution peuvent le dégrader ; la couverture végétale et des pratiques adaptées le protègent.',keyPoints:['Le sol contient matière minérale et organique','Le sol abrite des êtres vivants et retient l’eau','Végétation et pratiques adaptées limitent l’érosion'],exercises:[
    Exercise(id:'core_svt_5e_so1',lessonId:'core_svt_5e_soil',question:'Quelle matière contribue à former l’humus ?',options:['Des débris organiques décomposés','Du plastique neuf','Du métal fondu'],correctIndex:0,explanation:'L’humus provient de la transformation de matières organiques.'),
    Exercise(id:'core_svt_5e_so2',lessonId:'core_svt_5e_soil',question:'Quel phénomène peut emporter la terre fertile ?',options:['L’érosion','La condensation','La respiration'],correctIndex:0,explanation:'L’érosion peut entraîner les particules du sol par l’eau ou le vent.'),
    Exercise(id:'core_svt_5e_so3',lessonId:'core_svt_5e_soil',question:'Quel geste aide à protéger le sol ?',options:['Maintenir une couverture végétale','Brûler systématiquement les sols','Retirer toute végétation'],correctIndex:0,explanation:'La végétation protège le sol contre le ruissellement et l’érosion.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.quatrieme,code:'4e',unitOrder:3,title:'Reproduction des plantes à fleurs',lessonId:'core_svt_4e_flowering_plants',lessonTitle:'Comprendre pollinisation et formation des graines',summary:'Identifier les organes de la fleur et les étapes de la reproduction.',content:'Une fleur comporte notamment des étamines, qui produisent le pollen, et un pistil contenant les ovules. La pollinisation est le transport du pollen vers le stigmate, souvent par les insectes ou le vent. Après la fécondation, l’ovule devient une graine et l’ovaire peut devenir un fruit. Les graines peuvent ensuite germer si les conditions sont favorables.',keyPoints:['Étamine : pollen ; pistil : ovules','Pollinisation : transport du pollen','Après fécondation : graine et fruit'],exercises:[
    Exercise(id:'core_svt_4e_fp1',lessonId:'core_svt_4e_flowering_plants',question:'Le pollen est produit par…',options:['Les étamines','Les racines','Les feuilles uniquement'],correctIndex:0,explanation:'Les étamines sont les organes mâles de la fleur qui produisent le pollen.'),
    Exercise(id:'core_svt_4e_fp2',lessonId:'core_svt_4e_flowering_plants',question:'La pollinisation correspond au…',options:['Transport du pollen vers le stigmate','Développement des racines','Dessèchement du fruit'],correctIndex:0,explanation:'La pollinisation permet le dépôt du pollen sur le stigmate.'),
    Exercise(id:'core_svt_4e_fp3',lessonId:'core_svt_4e_flowering_plants',question:'Après fécondation, l’ovule devient…',options:['Une graine','Une feuille','Une racine'],correctIndex:0,explanation:'L’ovule fécondé se développe en graine.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.quatrieme,code:'4e',unitOrder:4,title:'Qualité de l’eau et traitement',lessonId:'core_svt_4e_water_quality',lessonTitle:'Protéger et traiter l’eau',summary:'Distinguer eau potable, pollution et étapes simples du traitement.',content:'Une eau limpide n’est pas forcément potable. L’eau potable doit répondre à des critères sanitaires. Les traitements peuvent comprendre le décantation, la filtration et la désinfection, selon la qualité de l’eau et les installations. La protection des sources, l’assainissement et la limitation des rejets sont essentiels pour éviter la contamination. Ne goûte jamais une eau inconnue pour vérifier sa qualité.',keyPoints:['L’aspect clair ne garantit pas la potabilité','Traitement : étapes adaptées, dont filtration et désinfection','Prévenir les rejets et protéger les captages'],exercises:[
    Exercise(id:'core_svt_4e_wq1',lessonId:'core_svt_4e_water_quality',question:'Une eau claire est-elle toujours potable ?',options:['Non, elle peut contenir des microbes ou substances','Oui, toujours','Seulement si elle est froide'],correctIndex:0,explanation:'La potabilité dépend de critères sanitaires invisibles à l’œil nu.'),
    Exercise(id:'core_svt_4e_wq2',lessonId:'core_svt_4e_water_quality',question:'La filtration sert notamment à…',options:['Retenir certaines particules','Ajouter des déchets','Garantir seule toute potabilité'],correctIndex:0,explanation:'La filtration élimine des particules, mais ne remplace pas nécessairement la désinfection.'),
    Exercise(id:'core_svt_4e_wq3',lessonId:'core_svt_4e_water_quality',question:'Pour protéger une source d’eau, il faut…',options:['Éviter les rejets polluants','Jeter les huiles à proximité','Laver les pesticides dans le cours d’eau'],correctIndex:0,explanation:'Limiter les rejets protège les ressources en eau.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.quatrieme,code:'4e',unitOrder:5,title:'Digestion et absorption des nutriments',lessonId:'core_svt_4e_digestion',lessonTitle:'Suivre le devenir des aliments',summary:'Comprendre transformation des aliments et passage des nutriments dans le sang.',content:'La digestion transforme les aliments en nutriments grâce aux actions mécaniques et aux sucs digestifs. Elle se déroule dans le tube digestif. Dans l’intestin grêle, les nutriments traversent la paroi et passent dans le sang : c’est l’absorption intestinale. Le sang les transporte vers les organes, qui les utilisent pour fonctionner et se développer.',keyPoints:['Digestion : aliments transformés en nutriments','Intestin grêle : lieu principal d’absorption','Le sang transporte les nutriments vers les organes'],exercises:[
    Exercise(id:'core_svt_4e_dg1',lessonId:'core_svt_4e_digestion',question:'La digestion transforme les aliments en…',options:['Nutriments','Roches','Air uniquement'],correctIndex:0,explanation:'Les nutriments sont des substances simples utilisables par l’organisme.'),
    Exercise(id:'core_svt_4e_dg2',lessonId:'core_svt_4e_digestion',question:'L’absorption des nutriments se fait principalement dans…',options:['L’intestin grêle','La bouche seulement','La trachée'],correctIndex:0,explanation:'La paroi de l’intestin grêle permet le passage des nutriments vers le sang.'),
    Exercise(id:'core_svt_4e_dg3',lessonId:'core_svt_4e_digestion',question:'Après absorption, les nutriments sont transportés par…',options:['Le sang','Les cheveux','Les os uniquement'],correctIndex:0,explanation:'Le sang distribue les nutriments aux organes.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.quatrieme,code:'4e',unitOrder:6,title:'Roches, érosion et paysages',lessonId:'core_svt_4e_erosion',lessonTitle:'Expliquer l’évolution d’un paysage',summary:'Relier altération, transport et dépôt des matériaux.',content:'Les roches peuvent être altérées par l’eau, les variations de température, le vent et les êtres vivants. Les fragments sont transportés par le ruissellement, les rivières ou le vent. Lorsque l’énergie du transport diminue, les matériaux se déposent et forment des sédiments. La végétation et des aménagements adaptés peuvent limiter l’érosion des sols.',keyPoints:['Altération : désagrégation ou transformation des roches','Transport des fragments par l’eau ou le vent','Dépôt : accumulation de sédiments'],exercises:[
    Exercise(id:'core_svt_4e_er1',lessonId:'core_svt_4e_erosion',question:'L’érosion peut être provoquée par…',options:['L’eau et le vent','La lumière seule','Le son uniquement'],correctIndex:0,explanation:'L’eau et le vent peuvent user et transporter les matériaux.'),
    Exercise(id:'core_svt_4e_er2',lessonId:'core_svt_4e_erosion',question:'Le dépôt de matériaux transportés forme…',options:['Des sédiments','Des cellules','Des nuages de vapeur uniquement'],correctIndex:0,explanation:'Les matériaux déposés constituent des sédiments.'),
    Exercise(id:'core_svt_4e_er3',lessonId:'core_svt_4e_erosion',question:'Quel geste peut limiter l’érosion ?',options:['Maintenir la végétation','Retirer toutes les plantes','Creuser sans protection'],correctIndex:0,explanation:'Les racines stabilisent le sol et la végétation réduit le ruissellement.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.troisieme,code:'3e',unitOrder:4,title:'Reproduction humaine et santé',lessonId:'core_svt_3e_human_reproduction',lessonTitle:'Comprendre la reproduction et la prévention',summary:'Identifier les fonctions reproductrices et les principes de prévention sanitaire.',content:'À la puberté, les organes reproducteurs deviennent fonctionnels sous l’action des hormones. La reproduction humaine nécessite la rencontre d’un spermatozoïde et d’un ovule ; la fécondation peut conduire au développement d’un embryon puis d’un fœtus. La santé reproductive repose sur l’information fiable, le respect, la prévention des infections sexuellement transmissibles et l’accès aux conseils de professionnels de santé.',keyPoints:['La puberté est accompagnée de changements hormonaux','Fécondation : rencontre d’un spermatozoïde et d’un ovule','Prévention et conseils de santé fiables'],exercises:[
    Exercise(id:'core_svt_3e_hr1',lessonId:'core_svt_3e_human_reproduction',question:'La fécondation correspond à…',options:['La rencontre des gamètes','La respiration des cellules','La formation d’une roche'],correctIndex:0,explanation:'La fécondation est la fusion d’un spermatozoïde et d’un ovule.'),
    Exercise(id:'core_svt_3e_hr2',lessonId:'core_svt_3e_human_reproduction',question:'À la puberté, les changements sont notamment liés…',options:['Aux hormones','Aux roches du sol','À la météo uniquement'],correctIndex:0,explanation:'Les hormones participent au déclenchement des changements de la puberté.'),
    Exercise(id:'core_svt_3e_hr3',lessonId:'core_svt_3e_human_reproduction',question:'Pour une question de santé reproductive, il est important de…',options:['Chercher une information fiable et un professionnel de santé','Se fier à des rumeurs','Éviter toute information'],correctIndex:0,explanation:'Une information fiable et un conseil professionnel favorisent la santé.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.troisieme,code:'3e',unitOrder:5,title:'Défenses immunitaires et vaccination',lessonId:'core_svt_3e_immunity',lessonTitle:'Découvrir les défenses de l’organisme',summary:'Comprendre les barrières, la réaction immunitaire et le rôle de la vaccination.',content:'L’organisme possède des barrières comme la peau et les muqueuses. Si un micro-organisme franchit ces barrières, des cellules immunitaires peuvent le reconnaître et agir. Certains lymphocytes produisent des anticorps spécifiques. La vaccination prépare le système immunitaire à reconnaître un agent infectieux et contribue à réduire le risque de maladie grave, selon le vaccin et la maladie.',keyPoints:['Peau et muqueuses : barrières naturelles','Réponse immunitaire spécifique et anticorps','La vaccination prépare les défenses immunitaires'],exercises:[
    Exercise(id:'core_svt_3e_im1',lessonId:'core_svt_3e_immunity',question:'La peau joue notamment le rôle de…',options:['Barrière naturelle','Organe de digestion','Cellule nerveuse'],correctIndex:0,explanation:'La peau constitue une première barrière contre de nombreux agents.'),
    Exercise(id:'core_svt_3e_im2',lessonId:'core_svt_3e_immunity',question:'Les anticorps sont produits par…',options:['Certaines cellules immunitaires','Les roches','Les globules rouges uniquement'],correctIndex:0,explanation:'Certaines cellules immunitaires produisent des anticorps spécifiques.'),
    Exercise(id:'core_svt_3e_im3',lessonId:'core_svt_3e_immunity',question:'La vaccination aide le système immunitaire à…',options:['Reconnaître un agent infectieux','Oublier tous les microbes','Arrêter la circulation sanguine'],correctIndex:0,explanation:'La vaccination prépare une réponse immunitaire contre un agent ciblé.'),
  ]),
  AnnualSecondarySvtUnit(level:SchoolLevel.troisieme,code:'3e',unitOrder:6,title:'Respiration et circulation sanguine',lessonId:'core_svt_3e_respiration_circulation',lessonTitle:'Relier respiration, sang et besoins des organes',summary:'Expliquer les échanges gazeux et le transport du dioxygène.',content:'Dans les poumons, le dioxygène de l’air passe dans le sang au niveau des alvéoles, tandis qu’une partie du dioxyde de carbone passe du sang vers l’air expiré. La circulation sanguine transporte le dioxygène vers les organes et ramène le dioxyde de carbone. Les cellules utilisent le dioxygène et les nutriments pour libérer l’énergie nécessaire à leur fonctionnement.',keyPoints:['Échanges gazeux au niveau des alvéoles pulmonaires','Le sang transporte le dioxygène','Les cellules utilisent dioxygène et nutriments pour produire de l’énergie'],exercises:[
    Exercise(id:'core_svt_3e_rc1',lessonId:'core_svt_3e_respiration_circulation',question:'Le dioxygène passe de l’air au sang au niveau…',options:['Des alvéoles pulmonaires','De l’estomac','Des os uniquement'],correctIndex:0,explanation:'Les échanges gazeux se déroulent au niveau des alvéoles pulmonaires.'),
    Exercise(id:'core_svt_3e_rc2',lessonId:'core_svt_3e_respiration_circulation',question:'Le sang transporte le dioxygène vers…',options:['Les organes','Les cheveux uniquement','Le milieu extérieur seulement'],correctIndex:0,explanation:'Le sang distribue le dioxygène aux organes.'),
    Exercise(id:'core_svt_3e_rc3',lessonId:'core_svt_3e_respiration_circulation',question:'Les cellules utilisent le dioxygène avec les nutriments pour…',options:['Libérer de l’énergie','Fabriquer des roches','Arrêter leur activité'],correctIndex:0,explanation:'La respiration cellulaire libère l’énergie utilisable par les cellules.'),
  ]),

];

final annualSecondarySvtChapters = annualSecondarySvtUnits.map((unit) => Chapter(
  id:unit.chapterId,subjectId:unit.subjectId,title:'Unité ${unit.unitOrder} — ${unit.title}',
  order:unit.unitOrder,term:unit.unitOrder,totalLessons:1,
)).toList();

final annualSecondarySvtLessons = annualSecondarySvtUnits.map((unit) => Lesson(
  id:unit.lessonId,chapterId:unit.chapterId,title:unit.lessonTitle,
  summary:unit.summary,content:unit.content,keyPoints:unit.keyPoints,durationMinutes:25,
)).toList();

final annualSecondarySvtExercises = annualSecondarySvtUnits.expand((unit)=>unit.exercises).toList();
